// Test component for complex integration testing

import { CommonModule } from '@angular/common'
import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Inject,
} from '@angular/core'
import { state, sequences } from 'cerebral'
import { CerebralComponent } from '../src/CerebralComponent'
import { AppService } from '../src/AppService'
import { connect } from '../src/connect'
import { TestSubComponent } from './TestSubComponent'

/**
 * Connected test component
 */
@Component({
  selector: 'test-app',
  template: `
    <input id="count" [value]="count" />
    <div id="increase" (click)="increase()">Increase</div>
    <test-sub-component
      id="subComponent"
      [subCompObj]="subCompObj"
    ></test-sub-component>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: true,
  imports: [TestSubComponent, CommonModule],
})
@connect({
  count: state`count`,
  subCompObj: state`subCompObj`,
  increase: sequences`increase`,
})
export class TestComponent extends CerebralComponent {
  count!: number
  subCompObj!: any
  increase!: () => void

  constructor(
    @Inject(ChangeDetectorRef) cdr: ChangeDetectorRef,
    @Inject(AppService) appService: AppService
  ) {
    super(cdr, appService)
  }
}
